      await stack.pkgManager.install(apkBytes, { filenameHint: 'a1214.apk' });
      const launched = await stack.pkgManager.launch('com.omnios.a1214');
      stack.kernel.scheduler.runUntilIdle(launched.pid, 300);

      assert.equal(getExitCode(stack.kernel, launched.pid), 0);
