            asm.label('u_err');
            asm.movToRbpDisp32(-0x38, R.RAX);
            asm.addRI64(R.R14, 1);
            asm.label('u_next');
            asm.addRI64(R.R12, 1);
            asm.jmp('u_loop');

            asm.label('u_done');
            asm.leaRipRel(R.RCX, 's_out');
            asm.movRR64(R.RDX, R.R13);
            asm.movRR64(R.R8, R.R14);
            asm.movFromRbpDisp32(R.R9, -0x38);
            asm.callIat('iat:printf');

