            asm.movFromRbpDisp32(R.RAX, -0x5c);
            asm.movToRspDisp64(0x20, R.RAX);
            asm.movFromRbpDisp32(R.RAX, -0x60);
            asm.movToRspDisp64(0x28, R.RAX);
            asm.movFromRbpDisp32(R.RAX, -0x64);
            asm.movToRspDisp64(0x30, R.RAX);
            asm.movFromRbpDisp32(R.RAX, -0x68);
            asm.movToRspDisp64(0x38, R.RAX);
            asm.movFromRbpDisp32(R.RAX, -0x6c);
