        assert.ok(updates >= 1 && updates <= 50, `Expected coalesced GetMessageA updates in [1..50], got ${updates}`);
        assert.equal(lastTitle, 'GM_1999', `Expected final title GM_1999, got ${lastTitle}`);
        assert.equal(lastChildren, 250, `Expected 250 children, got ${lastChildren}`);
