            asm.movImm32ToRspDisp64(0x48, 0);
            asm.movImm32ToRspDisp64(0x50, 0);
            asm.movImm32ToRspDisp64(0x58, 0);
            asm.callIat('iat:CreateWindowExA');

            asm.xorRR32(R.RCX, R.RCX);
            asm.callIat('iat:ExitProcess');
