            asm.leaRipRel(R.RDX, 's_child');
            asm.xorRR32(R.R8, R.R8);
            asm.movRI32(R.R9, 0x20019);
            asm.leaRbpDisp(R.RAX, -0x40);
            asm.movToRspDisp64(0x20, R.RAX);
            asm.callIat('iat:RegOpenKeyExA');
            asm.movRR64(R.R13, R.RAX);

            asm.movImm32ToRbpDisp32(-0x48, 128);
            asm.movRR64(R.RCX, R.RBX);
            asm.xorRR32(R.RDX, R.RDX);
            asm.leaRipRel(R.R8, 'enum_name');
            asm.leaRbpDisp(R.R9, -0x48);
            asm.movImm32ToRspDisp64(0x20, 0);
            asm.movImm32ToRspDisp64(0x28, 0);
            asm.movImm32ToRspDisp64(0x30, 0);
            asm.movImm32ToRspDisp64(0x38, 0);
            asm.callIat('iat:RegEnumKeyExA');
            asm.movRR64(R.R14, R.RAX);

            asm.leaRipRel(R.RCX, 's_fmt1');
            asm.movRR64(R.RDX, R.R13);
            asm.movRR64(R.R8, R.R14);
            asm.callIat('iat:printf');

            // Yield across multiple scheduler ticks so concurrent Process B creates PeerChild
            asm.xorRR32(R.R12, R.R12);
            asm.label('spin_a');
            asm.cmpRI64(R.R12, 25000);
            asm.jge('spin_a_done');
            asm.addRI64(R.R12, 1);
            asm.jmp('spin_a');
            asm.label('spin_a_done');

            asm.movRI64(R.RCX, BigInt(WIN32_CONSTANTS.HKEY_CURRENT_USER));
            asm.leaRipRel(R.RDX, 's_child');
            asm.xorRR32(R.R8, R.R8);
            asm.movRI32(R.R9, 0x20019);
            asm.leaRbpDisp(R.RAX, -0x40);
            asm.movToRspDisp64(0x20, R.RAX);
            asm.callIat('iat:RegOpenKeyExA');
            asm.movRR64(R.R13, R.RAX);
            asm.cmpRI64(R.RAX, 0);
            asm.jne('skip_close_a');
            asm.movFromRbpDisp64(R.RCX, -0x40);
            asm.callIat('iat:RegCloseKey');
            asm.label('skip_close_a');

            asm.movImm32ToRbpDisp32(-0x48, 128);
            asm.movRR64(R.RCX, R.RBX);
            asm.xorRR32(R.RDX, R.RDX);
            asm.leaRipRel(R.R8, 'enum_name');
            asm.leaRbpDisp(R.R9, -0x48);
            asm.movImm32ToRspDisp64(0x20, 0);
            asm.movImm32ToRspDisp64(0x28, 0);
            asm.movImm32ToRspDisp64(0x30, 0);
            asm.movImm32ToRspDisp64(0x38, 0);
