            asm.movRR64(R.R14, R.RAX);

            asm.leaRipRel(R.RCX, 's_fmt2');
            asm.movRR64(R.RDX, R.R13);
            asm.movRR64(R.R8, R.R14);
            asm.leaRipRel(R.R9, 'enum_name');
