            asm.xorRR32(R.R9, R.R9);
            asm.movImm32ToRspDisp64(0x20, 0);
            asm.movImm32ToRspDisp64(0x28, 0);
            asm.movImm32ToRspDisp64(0x30, 0);
            asm.leaRbpDisp(R.RAX, -0x28);
            asm.movToRspDisp64(0x38, R.RAX);
            asm.movImm32ToRspDisp64(0x40, 0);
